/// Shape Adjust (ECMA-376 Part 1 §21.4.2.1).
///
/// Shape adjust value. These can be used to modify the adjust handles supported on various auto shapes. It is only possible to set the initial value, not to modify it using constraints and rules.
///
/// Schema type `CT_Adj`, used by:
///
/// * `dgm:adj` — Shape Adjust (§21.4.2.1)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_Adj {
    /// `idx` — Adjust Handle Index. Adjust value index. Required by the schema.
    pub idx: Option<ST_Index1>,
    /// `val` — Value. An absolute value. Required by the schema.
    pub val: Option<f64>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_Adj {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "idx") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.idx = Some(v);
                        continue;
                    }
                }
                (Ns::NONE, "val") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.val = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            while let Some(child) = r.next_child()? {
                let raw = RawElement::read(r, &child)?;
                rt::push_extra(&mut this.extra_children, 0, raw);
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_Adj {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "idx", &self.idx);
        rt::write_attr(w, Ns::NONE, "val", &self.val);
        w.attrs_raw(&self.extra_attrs);
        rt::write_extras(w, &self.extra_children, 0);
        w.end();
    }
}

impl Validate for CT_Adj {
    fn validate(&self, v: &mut Validator) {
        if self.idx.is_none() {
            v.required_attribute(Ns::NONE, "idx", &self.extra_attrs);
        }
        if self.val.is_none() {
            v.required_attribute(Ns::NONE, "val", &self.extra_attrs);
        }
    }
}

/// Shape Adjust List (ECMA-376 Part 1 §21.4.2.2).
///
/// This element is simply a list of shape adjusts.
///
/// Schema type `CT_AdjLst`, used by:
///
/// * `dgm:adjLst` — Shape Adjust List (§21.4.2.2)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_AdjLst {
    /// `dgm:adj` — Shape Adjust (§21.4.2.1).
    pub adj: Vec<CT_Adj>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_AdjLst {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::DGM, "adj") => {
                        this.adj.push(XmlRead::read_xml(r, &child)?);
                        pos = 1;
                    }
                    _ => match pos {
                        1 => rt::push_extra_at(
                            &mut this.extra_children,
                            0,
                            this.adj.len(),
                            RawElement::read(r, &child)?,
                        ),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_AdjLst {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        w.attrs_raw(&self.extra_attrs);
        for (k, v) in self.adj.iter().enumerate() {
            rt::write_extras_at(w, &self.extra_children, 0, k);
            v.write_xml(w, Ns::DGM, "adj");
        }
        rt::write_extras_after(w, &self.extra_children, 0, self.adj.len());
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_AdjLst {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.adj.iter().enumerate() {
            v.enter("dgm:adj", Some(i), |v| x.validate(v));
        }
    }
}

/// Algorithm (ECMA-376 Part 1 §21.4.2.3).
///
/// The algorithm used by the containing layout node. The algorithm defines the behavior of the layout node along with the behavior and layout of the nested layout nodes.
///
/// Schema type `CT_Algorithm`, used by:
///
/// * `dgm:alg` — Algorithm (§21.4.2.3)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_Algorithm {
    /// `type` — Algorithm Type. Specifies the algorithm type. Required by the schema.
    pub type_: Option<ST_AlgorithmType>,
    /// `rev` — Revision Number. The revision number of an algorithm. Default: `0`.
    pub rev: Option<u32>,
    /// `dgm:param` — Parameter (§21.4.2.20).
    pub param: Vec<CT_Parameter>,
    /// `dgm:extLst` — Extension List (§21.4.2.13).
    pub ext_lst: Option<Box<crate::dml::CT_OfficeArtExtensionList>>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_Algorithm {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "type") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.type_ = Some(v);
                        continue;
                    }
                }
                (Ns::NONE, "rev") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.rev = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::DGM, "param") => {
                        this.param.push(XmlRead::read_xml(r, &child)?);
                        pos = 1;
                    }
                    (Ns::DGM, "extLst") => {
                        if this.ext_lst.is_none() {
                            this.ext_lst = Some(Box::new(XmlRead::read_xml(r, &child)?));
                        } else {
                            rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?);
                        }
                        pos = 2;
                    }
                    _ => match pos {
                        1 => rt::push_extra_at(
                            &mut this.extra_children,
                            0,
                            this.param.len(),
                            RawElement::read(r, &child)?,
                        ),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_Algorithm {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "type", &self.type_);
        rt::write_attr(w, Ns::NONE, "rev", &self.rev);
        w.attrs_raw(&self.extra_attrs);
        for (k, v) in self.param.iter().enumerate() {
            rt::write_extras_at(w, &self.extra_children, 0, k);
            v.write_xml(w, Ns::DGM, "param");
        }
        rt::write_extras_after(w, &self.extra_children, 0, self.param.len());
        rt::write_extras(w, &self.extra_children, 1);
        if let Some(v) = &self.ext_lst {
            v.write_xml(w, Ns::DGM, "extLst");
        }
        rt::write_extras(w, &self.extra_children, 2);
        w.end();
    }
}

impl Validate for CT_Algorithm {
    fn validate(&self, v: &mut Validator) {
        if self.type_.is_none() {
            v.required_attribute(Ns::NONE, "type", &self.extra_attrs);
        }
        for (i, x) in self.param.iter().enumerate() {
            v.enter("dgm:param", Some(i), |v| x.validate(v));
        }
        if let Some(x) = &self.ext_lst {
            v.enter("dgm:extLst", None, |v| x.validate(v));
        }
    }
}

