/// Color Transform Category List (ECMA-376 Part 1 §21.4.4.2).
///
/// This element defines a list of color transform categories. This list can be used to populate user interface components which could separate color transforms into categories.
///
/// Schema type `CT_CTCategories`, used by:
///
/// * `dgm:catLst` — Color Transform Category List (§21.4.4.2)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_CTCategories {
    /// `dgm:cat` — Color Transform Category (§21.4.4.1).
    pub cat: Vec<CT_CTCategory>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_CTCategories {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::DGM, "cat") => {
                        this.cat.push(XmlRead::read_xml(r, &child)?);
                        pos = 1;
                    }
                    _ => match pos {
                        1 => rt::push_extra_at(
                            &mut this.extra_children,
                            0,
                            this.cat.len(),
                            RawElement::read(r, &child)?,
                        ),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_CTCategories {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        w.attrs_raw(&self.extra_attrs);
        for (k, v) in self.cat.iter().enumerate() {
            rt::write_extras_at(w, &self.extra_children, 0, k);
            v.write_xml(w, Ns::DGM, "cat");
        }
        rt::write_extras_after(w, &self.extra_children, 0, self.cat.len());
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_CTCategories {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.cat.iter().enumerate() {
            v.enter("dgm:cat", Some(i), |v| x.validate(v));
        }
    }
}

